const mez = (h: string, k: number) => { const n = parseInt(h.slice(1), 16); const f = (v: number) => Math.round(k < 0 ? v * (1 + k) : v + (255 - v) * k); return `rgb(${f(n >> 16)},${f((n >> 8) & 255)},${f(n & 255)})`; };
const Vol: React.FC<{d: string; c: string}> = ({d, c}) => <g><path d={d} fill={c} /><path d={d} fill="url(#vol)" /></g>;
type Cara = 'neutra' | 'feliz' | 'susto' | 'triste' | 'enojo' | 'duda';
const PIEL = {blanca: '#f9dfcd', clara: '#eec3a0', media: '#d39a70', canela: '#b57a50', morena: '#8a5636', oscura: '#5f3a26'};
const TONOS = [PIEL.blanca, PIEL.clara, PIEL.media, PIEL.blanca, PIEL.canela, PIEL.clara, PIEL.morena, PIEL.oscura];
const tonoDe = (rasgos: string) => {
let n = 0;
for (let i = 0; i < rasgos.length; i++) n = (n * 31 + rasgos.charCodeAt(i)) % 9973;
return TONOS[n % TONOS.length];
};
const Rostro: React.FC<{cara: Cara; piel: string; habla: number; mira: number; s: number; pelo: string; ojo: string; mujer: boolean}> = ({cara, piel, habla, mira, s, pelo, ojo, mujer}) => {
const parp = Math.sin(s * 2.1) > 0.985 ? 0.1 : 1;
const ab = cara === 'susto' ? 1.3 : 1;
const ceja = {neutra: 0, feliz: -3, susto: -11, triste: -2, enojo: 5, duda: -5}[cara];
const inc = {neutra: 0, feliz: 0, susto: -6, triste: -13, enojo: 14, duda: 0}[cara];
const bx = 15 + habla * 3, by = 4 + habla * 11 + (cara === 'susto' ? 12 : 0);
const labio = mujer ? '#b5474f' : mez(piel, -0.28);
return (
<g>
{[-1, 1].map((l) => (
<g key={l} transform={`translate(${l * 34} -874)`}>
<ellipse cx={0} cy={0} rx={18} ry={9.5 * parp * ab} fill="#f6f1ea" />
{parp > 0.5 ? <g><circle cx={mira * 6} cy={0} r={8.8} fill={ojo} /><circle cx={mira * 6} cy={0} r={4.3} fill="#15110e" /><circle cx={mira * 6 + 3} cy={-3} r={2} fill="#fff" /></g> : null}
<path d={`M-19 1Q0 ${-14 * ab} 19 1`} fill="none" stroke={mez(pelo, -0.3)} strokeWidth={3.6} strokeLinecap="round" />
<path d={`M-14 8Q0 13 14 8`} fill="none" stroke={mez(piel, -0.25)} strokeWidth={1.8} />
<path d={`M${-22} ${-23 + ceja}Q0 ${-32 + ceja} 22 ${-24 + ceja}L21 ${-19 + ceja}Q0 ${-26 + ceja} -22 ${-18 + ceja}Z`} fill={mez(pelo, -0.1)}
transform={`rotate(${l * inc + (cara === 'duda' && l > 0 ? -9 : 0)} 0 -22)`} />
</g>
))}
<path d="M6 -860Q14 -846 15 -834Q6 -826 -4 -830Q0 -846 6 -860Z" fill={mez(piel, -0.3)} opacity={0.14} />
<path d="M-15 -834Q-8 -826 0 -827Q8 -826 15 -834" fill="none" stroke={mez(piel, -0.32)} strokeWidth={3} strokeLinecap="round" />
<ellipse cx={-2} cy={-844} rx={5} ry={9} fill="#fff" opacity={0.18} />
<ellipse cx={-46} cy={-834} rx={19} ry={11} fill="#c9503f" opacity={0.05} /><ellipse cx={46} cy={-834} rx={19} ry={11} fill="#c9503f" opacity={0.05} />
{cara === 'feliz'
? <g><path d={`M-26 -806Q0 ${-790 + habla * 10} 26 -806Q0 -801 -26 -806Z`} fill="#6e2a2a" /><path d="M-22 -805Q0 -799 22 -805L19 -800Q0 -795 -19 -800Z" fill="#f7f3ec" /><path d="M-29 -807Q0 -813 29 -807" fill="none" stroke={labio} strokeWidth={4} strokeLinecap="round" /></g>
: by > 7
? <g><ellipse cx={0} cy={-802} rx={bx} ry={by} fill="#4a1c1c" /><path d={`M${-bx * 0.72} ${-802 - by * 0.72}Q0 ${-802 - by * 1.1} ${bx * 0.72} ${-802 - by * 0.72}Q0 ${-802 - by * 0.5} ${-bx * 0.72} ${-802 - by * 0.72}Z`} fill="#f7f3ec" /><ellipse cx={0} cy={-802} rx={bx + 2} ry={by + 2} fill="none" stroke={labio} strokeWidth={4} /></g>
: <path d={cara === 'triste' || cara === 'enojo' ? 'M-20 -798Q0 -810 20 -798' : 'M-20 -804Q0 -800 20 -804'} fill="none" stroke={labio} strokeWidth={5.5} strokeLinecap="round" />}
</g>
);
