/** PERSONA adulta de dibujo semirrealista. Origen en los pies; mide 1000 de alto. Va con <Pon x y e>. e 0.9 de cuerpo entero; para primer plano e 3 con y cerca de 3300.
* edad: 0 joven, 1 mayor (canas y arrugas). pelo: corto | largo | rizo | calvo. abierto: enseña los órganos reales del tronco (pega también ESTILO_organos). */
const Persona: React.FC<{cara?: Cara; piel?: string; pelo?: string; peinado?: 'corto' | 'largo' | 'rizo' | 'calvo'; ropa?: string; pantalon?: string; zapato?: string; ojo?: string; mujer?: boolean; barba?: boolean; gafas?: boolean; edad?: number; bata?: boolean; habla?: number; mira?: number; pasos?: number; brazoI?: number; brazoD?: number; abierto?: React.ReactNode; children?: React.ReactNode}> =
({cara = 'neutra', piel: pielDada, pelo = '#2b1d14', peinado, ropa = '#33566e', pantalon = '#2c3442', zapato = '#2a2118', ojo = '#4a2f1c', mujer = false, barba = false, gafas = false, edad = 0, bata = false, habla = 0, mira = 0, pasos = 0, brazoI = 0, brazoD = 0, abierto, children}) => {
const {s} = useS();
const piel = pielDada || tonoDe([ropa, pelo, peinado, mujer, barba].join('|'));
const p = Math.sin(s * 8) * 26 * pasos;
const res = Math.sin(s * 2.3) * 3;
const pl = edad > 0.5 ? '#c9c6c0' : pelo;
const pe = peinado ?? (mujer ? 'largo' : 'corto');
const tela = bata ? '#f2f3f1' : ropa;
const hombro = mujer ? 104 : 124, cint = mujer ? 74 : 92, cad = mujer ? 104 : 96;
const tronco = `M${-hombro} -690C${-hombro + 30} -726 -72 -738 -40 -750H40C72 -738 ${hombro - 30} -726 ${hombro} -690Q${hombro + 12} -630 ${cint} -520L${cad} -440H${-cad}L${-cint} -520Q${-hombro - 12} -630 ${-hombro} -690Z`;
const Brazo = (l: number, a: number) => (
<g transform={`rotate(${-l * (10 + a * 140)} ${l * (hombro - 8)} -702)`}>
